NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Ezra'

CHAPTERS = {
    1: {
        1: 'In anno primo Cyri regis Persarum ut compleretur verbum Domini ex ore Ieremiae, suscitavit Dominus spiritum Cyri regis Persarum: et traduxit vocem in omni regno suo, etiam per scripturam, dicens:',
        2: 'Haec dicit Cyrus rex Persarum: Omnia regna terrae dedit mihi Dominus Deus caeli, et ipse praecepit mihi ut aedificarem ei domum in Ierusalem, quae est in Iudaea.',
        3: 'Quis est in vobis de universo populo eius? Sit Deus illius cum ipso. Ascendat in Ierusalem, quae est in Iudaea, et aedificet domum Domini Dei Israel, ipse est Deus qui est in Ierusalem.',
        4: 'Et omnes reliqui in cunctis locis ubicumque habitant, adiuvent eum viri de loco suo argento et auro, et substantia, et pecoribus, excepto quod voluntarie offerunt templo Dei, quod est in Ierusalem.',
        5: 'Et surrexerunt principes patrum de Iuda, et Beniamin, et Sacerdotes, et Levitae, et omnis, cuius Deus suscitavit spiritum, ut ascenderent ad aedificandum templum Domini, quod erat in Ierusalem.',
        6: 'Universique qui erant in circuitu, adiuverunt manus eorum in vasis argenteis et aureis, in substantia et iumentis, in supellectili, exceptis his, quae sponte obtulerant.',
        7: 'Rex quoque Cyrus protulit vasa templi Domini, quae tulerat Nabuchodonosor de Ierusalem, et posuerat ea in templo Dei sui.',
        8: 'Protulit autem ea Cyrus rex Persarum per manum Mithridatis filii Gazabar, et annumeravit ea Sassabasar principi Iuda.',
        9: 'Et hic est numerus eorum: Phialae aureae triginta, phialae argenteae mille, cultri vigintinovem, scyphi aurei triginta,',
        10: 'scyphi argentei secundi quadringenti decem: vasa alia mille.',
        11: 'Omnia vasa aurea et argentea quinque millia quadringenta: universa tulit Sassabasar cum his, qui ascendebant de transmigratione Babylonis in Ierusalem.',
    },
    2: {
        1: 'Hi sunt autem provinciae filii, qui ascenderunt de captivitate, quam transtulerat Nabuchodonosor rex Babylonis in Babylonem, et reversi sunt in Ierusalem et Iuda, unusquisque in civitatem suam.',
        2: 'Qui venerunt cum Zorobabel, Iosue, Nehemia, Saraia, Rahelaia, Mardochai, Belsan, Mesphar, Beguai, Rehum, Baana. Numerus virorum populi Israel:',
        3: 'Filii Pharos duo millia centum septuagintaduo.',
        4: 'Filii Sephatia, trecenti septuagintaduo.',
        5: 'Filii Area, septingenti septuagintaquinque.',
        6: 'Filii Phahath Moab, filiorum Iosue: Ioab duo millia octingenti duodecim.',
        7: 'Filii Aelam mille ducenti quinquagintaquattuor.',
        8: 'Filii Zethua, nongenti quadragintaquinque.',
        9: 'Filii Zachai, septingenti sexaginta.',
        10: 'Filii Bani, sexcenti quadragintaduo.',
        11: 'Filii Bebai, sexcenti vigintitres.',
        12: 'Filii Azgad, mille ducenti viginti duo.',
        13: 'Filii Adonicam, sexcenti sexagintasex.',
        14: 'Filii Beguai, duo millia quinquagintasex.',
        15: 'Filii Adin, quadringenti quinquagintaquattuor.',
        16: 'Filii Ather, qui erant ex Ezechia, nonagintaocto.',
        17: 'Filii Besai, trecenti vigintitres.',
        18: 'Filii Iora, centum duodecim.',
        19: 'Filii Hasum, ducenti vigintitres.',
        20: 'Filii Gebbar, nonagintaquinque.',
        21: 'Filii Bethlehem, centum vigintitres.',
        22: 'Viri Netupha, quinquagintasex.',
        23: 'Viri Anathoth, centum vigintiocto.',
        24: 'Filii Azmaveth, quadraginta duo.',
        25: 'Filii Cariathiarim, Cephira, et Beroth, septingenti quadragintatres.',
        26: 'Filii Rama et Gabaa, sexcenti vigintiunus.',
        27: 'Viri Machmas, centum viginti duo.',
        28: 'Viri Bethel et Hai, ducenti vigintitres.',
        29: 'Filii Nebo, quinquagintaduo.',
        30: 'Filii Megbis, centum quinquagintasex.',
        31: 'Filii Aelam alterius, mille ducenti quinquagintaquattuor.',
        32: 'Filii Harim, trecenti viginti.',
        33: 'Filii Lod Hadid, et Ono, septingenti vigintiquinque.',
        34: 'Filii Iericho, trecenti quadragintaquinque.',
        35: 'Filii Senaa, tria millia sexcenti triginta.',
        36: 'Sacerdotes: Filii Iadaia in domo Iosue nongenti septuaginta tres.',
        37: 'Filii Emmer, mille quinquagintaduo.',
        38: 'Filii Pheshur, mille ducenti quadraginta septem.',
        39: 'Filii Harim, mille decem et septem.',
        40: 'Levitae: Filii Iosue et Cedmihel filiorum Odoviae septuagintaquattuor.',
        41: 'Cantores: Filii Asaph, centum vigintiocto.',
        42: 'Filii Ianitorum: filii Sellum, filii Ater, filii Telmon, filii Accub, filii Hatita, filii Sobai: universi centum trigintanovem.',
        43: 'Nathinaei: filii Siha, filii Hasupha, filii Tabbaoth,',
        44: 'filii Ceros, filii Siaa, filii Phadon,',
        45: 'filii Lebana, filii Hagaba, filii Accub,',
        46: 'filii Hagab, filii Semlai, filii Hanan,',
        47: 'filii Gaddel, filii Gaher, filii Raaia,',
        48: 'filii Rasin, filii Necoda, filii Gazam,',
        49: 'filii Aza, filii Phasea, filii Besee,',
        50: 'filii Asena, filii Munim, filii Nephusim,',
        51: 'filii Bacbuc, filii Hacupha, filii Harhur,',
        52: 'filii Besluth, filii Mahida, filii Harsa,',
        53: 'filii Bercos, filii Sisara, filii Thema,',
        54: 'filii Nasia, filii Hatipha,',
        55: 'filii servorum Salomonis, filii Sotai, filii Sophereth, filii Pharuda,',
        56: 'filii Iala, filii Dercon, filii Geddel,',
        57: 'filii Saphatia, filii Hatil, filii Phochereth, qui erant de Asebaim, filii Ami.',
        58: 'omnes Nathinaei, et filii servorum Salomonis, trecenti nonagintaduo.',
        59: 'Et hi qui ascenderunt de Thelmala, Thelharsa, Cherub, et Adon, et Emer: et non potuerunt indicare domum patrum suorum et semen suum, utrum ex Israel essent.',
        60: 'Filii Dalaia, filii Tobia, filii Necoda, sexcenti quinquagintaduo.',
        61: 'Et de filiis Sacerdotum: Filii Hobia, filii Accos, filii Berzellai, qui accepit de filiabus Berzellai Galaaditis, uxorem, et vocatus est nomine eorum:',
        62: 'hi quaesierunt scripturam genealogiae suae, et non invenerunt, et eiecti sunt de sacerdotio.',
        63: 'Et dixit Athersatha eis ut non comederent de Sancto sanctorum, donec surgeret sacerdos doctus atque perfectus.',
        64: 'Omnis multitudo quasi unus, quadraginta duo millia trecenti sexaginta:',
        65: 'exceptis servis eorum, et ancillis, qui erant septem millia trecenti trigintaseptem: et in ipsis cantores, atque cantatrices ducenti.',
        66: 'Equi eorum sexcenti triginta sex, muli eorum, ducenti quadragintaquinque,',
        67: 'cameli eorum, quadringenti trigintaquinque, asini eorum, sex millia septingenti viginti.',
        68: 'Et de principibus patrum, cum ingrederentur templum Domini, quod est in Ierusalem, sponte obtulerunt in domum Dei ad extruendam eam in loco suo.',
        69: 'Secundum vires suas dederunt impensas operis, auri solidos quadraginta millia et mille, argenti mnas quinque millia, et vestes sacerdotales centum.',
        70: 'Habitaverunt ergo Sacerdotes, et Levitae, et de populo, et cantores, et ianitores, et Nathinaei in urbibus suis, universusque Israel in civitatibus suis.',
    },
    3: {
        1: 'Iamque venerat mensis septimus, et erant filii Israel in civitatibus suis: congregatus est ergo populus quasi vir unus in Ierusalem.',
        2: 'Et surrexit Iosue filius Iosedec, et fratres eius sacerdotes, et Zorobabel filius Salathiel, et fratres eius, et aedificaverunt altare Dei Israel ut offerrent in eo holocaustomata, sicut scriptum est in lege Moysi viri Dei:',
        3: 'Collocaverunt autem altare Dei super bases suas deterrentibus eos per circuitum populis terrarum, et obtulerunt super illud holocaustum Domino mane et vespere:',
        4: 'Feceruntque sollemnitatem tabernaculorum, sicut scriptum est, et holocaustum diebus singulis per ordinem secundum praeceptum opus diei in die suo.',
        5: 'Et post haec holocaustum iuge, tam in Calendis quam in universis sollemnitatibus Domini, quae erant consecratae, et in omnibus in quibus ultro offerebatur munus Domino.',
        6: 'A primo die mensis septimi coeperunt offerre holocaustum Domino: porro templum Dei nondum fundatum erat.',
        7: 'Dederunt autem pecunias latomis et caementariis: cibum quoque, et potum, et oleum Sidoniis, Tyriisque ut deferrent ligna cedrina de Libano ad mare Ioppes, iuxta quod praeceperat Cyrus rex Persarum eis.',
        8: 'Anno autem secundo adventus eorum ad templum Dei in Ierusalem mense secundo, coeperunt Zorobabel filius Salathiel, et Iosue filius Iosedec, et reliqui de fratribus eorum Sacerdotes, et Levitae, et omnes qui venerant de captivitate in Ierusalem, et constituerunt Levitas a viginti annis et supra, ut urgerent opus Domini.',
        9: 'Stetitque Iosue et filii eius, et fratres eius, Cedmihel, et filii eius, et filii Iuda, quasi vir unus, ut instarent super eos qui faciebant opus in templo Dei: filii Henadad, et filii eorum, et fratres eorum Levitae.',
        10: 'Fundato igitur a caementariis templo Domini, steterunt sacerdotes in ornatu suo cum tubis: et Levitae filii Asaph in cymbalis, ut laudarent Deum per manus David regis Israel.',
        11: 'Et concinebant in hymnis, et confessione Domino: Quoniam bonus, quoniam in aeternum misericordia eius super Israel. Omnis quoque populus vociferabatur clamore magno in laudando Dominum, eo quod fundatum esset templum Domini.',
        12: 'plurimi etiam de Sacerdotibus et Levitis, et principes patrum, et seniores, qui viderant templum prius cum fundatum esset, et hoc templum in oculis eorum, flebant voce magna: et multi vociferantes in laetitia, elevabant vocem.',
        13: 'Nec poterat quisquam agnoscere vocem clamoris laetantium, et vocem fletus populi: commixtim enim populus vociferabatur clamore magno, et vox audiebatur procul.',
    },
    4: {
        1: 'Audierunt autem hostes Iuda, et Beniamin, quia filii captivitatis aedificarent templum Domino Deo Israel:',
        2: 'et accedentes ad Zorobabel, et ad principes patrum dixerunt eis: Aedificemus vobiscum, quia ita ut vos, quaerimus Deum vestrum: ecce nos immolavimus victimas a diebus Asor Haddan regis Assur, qui adduxit nos huc.',
        3: 'Et dixit eis Zorobabel, et Iosue, et reliqui principes patrum Israel: Non est vobis et nobis ut aedificemus domum Deo nostro, sed nosipsi soli aedificabimus Domino Deo nostro, sicut praecepit nobis Cyrus rex Persarum.',
        4: 'Factum est igitur ut populus terrae impediret manus populi Iudae, et turbaret eos in aedificando.',
        5: 'Conduxerunt autem adversus eos consiliatores, ut destruerent consilium eorum omnibus diebus Cyri regis Persarum, et usque ad regnum Darii regis Persarum.',
        6: 'In regno autem Assueri, in principio regni eius, scripserunt accusationem adversus habitatores Iudae et Ierusalem.',
        7: 'Et in diebus Artaxerxis scripsit Beselam Mithridates, et Thabeel, et reliqui, qui erant in consilio eorum, ad Artaxerxem regem Persarum: epistola autem accusationis scripta erat Syriace, et legebatur sermone Syro.',
        8: 'Reum Beelteem, et Samsai scriba scripserunt epistolam unam de Ierusalem Artaxerxi regi, huiuscemodi:',
        9: 'Reum Beelteem, et Samsai scriba, et reliqui consiliatores eorum, Dinaei, et Apharsathachaei, Terphalaei, Apharsaei, Erchuae, Babylonii, Susanechaei, Dievi, et Aelamitae,',
        10: 'et ceteri de Gentibus, quas transtulit Asenaphar magnus et gloriosus: et habitare eas fecit in civitatibus Samariae, et in reliquis regionibus trans Flumen in pace:',
        11: '(Hoc est exemplar epistolae, quam miserunt ad eum) Artaxerxi regi, servi tui, viri qui sunt trans Fluvium, salutem dicunt.',
        12: 'Notum sit regi, quia Iudaei, qui ascenderunt a te ad nos, venerunt in Ierusalem civitatem rebellem et pessimam, quam aedificant extruentes muros eius, et parietes componentes.',
        13: 'Nunc igitur notum sit regi, quia si civitas illa aedificata fuerit, et muri eius instaurati, tributum, et vectigal, et annuos reditus non dabunt, et usque ad reges haec noxa perveniet.',
        14: 'Nos autem memores salis, quod in palatio comedimus, et quia laesiones regis videre nefas ducimus, idcirco misimus et nunciavimus regi,',
        15: 'ut recenseas in libris historiarum patrum tuorum, et invenies scriptum in commentariis: et scies quoniam urbs illa, urbs rebellis est, et nocens regibus et provinciis, et bella concitantur in ea ex diebus antiquis: quam ob rem et civitas ipsa destructa est.',
        16: 'Nunciamus nos regi, quoniam si civitas illa aedificata fuerit, et muri ipsius instaurati, possessionem trans Fluvium non habebis.',
        17: 'Verbum misit rex ad Reum Beelteem, et Samsai scribam, et ad reliquos, qui erant in consilio eorum habitatores Samariae, et ceteris trans Fluvium, salutem dicens et pacem.',
        18: 'Accusatio, quam misistis ad nos, manifeste lecta est coram me.',
        19: 'et a me praeceptum est: et recensuerunt, inveneruntque quoniam civitas illa a diebus antiquis adversum reges rebellat, et seditiones, et praelia concitantur in ea:',
        20: 'nam et reges fortissimi fuerunt in Ierusalem, qui et dominati sunt omni regioni. quae trans Fluvium est: tributum quoque et vectigal, et reditus accipiebant.',
        21: 'Nunc ergo audite sententiam: Prohibeatis viros illos ut urbs illa non aedificetur, donec si forte a me iussum fuerit.',
        22: 'Videte ne negligenter hoc impleatis, et paulatim crescat malum contra reges.',
        23: 'Itaque exemplum edicti Artaxerxis regis lectum est coram Reum Beelteem, et Samsai scriba, et consiliariis eorum: et abierunt festini in Ierusalem ad Iudaeos, et prohibuerunt eos in brachio et robore.',
        24: 'Tunc intermissum est opus domus Domini in Ierusalem, et non fiebat usque ad annum secundum regni Darii regis Persarum.',
    },
    5: {
        1: 'Prophetaverunt autem Aggaeus Propheta, et Zacharias filius Addo prophetantes ad Iudaeos, qui erant in Iudaea et Ierusalem, in nomine Dei Israel.',
        2: 'Tunc surrexerunt Zorobabel filius Salathiel, et Iosue filius Iosedec, et coeperunt aedificare templum Dei in Ierusalem, et cum eis prophetae Dei adiuvantes eos.',
        3: 'In ipso autem tempore venit ad eos Thathanai, qui erat dux trans Flumen, et Stharbuzanai, et consiliarii eorum: sicque dixerunt eis: Quis dedit vobis consilium ut domum hanc aedificaretis, et muros eius instauraretis?',
        4: 'Ad quod respondimus eis, quae essent nomina hominum auctorum aedificationis illius.',
        5: 'Oculus autem Dei eorum factus est super senes Iudaeorum, et non potuerunt inhibere eos. Placuitque ut res ad Darium referretur, et tunc satisfacerent adversus accusationem illam.',
        6: 'Exemplar epistolae, quam misit Thathanai dux regionis trans Flumen, et Stharbuzanai, et consiliatores eius Arphasachaei, qui erant trans Flumen, ad Darium regem.',
        7: 'Sermo, quem miserant ei, sic scriptus erat: Dario regi pax omnis.',
        8: 'Notum sit regi, isse nos ad Iudaeam provinciam, ad domum Dei magni, quae aedificatur lapide impolito, et ligna ponuntur in parietibus: opusque illud diligenter extruitur, et crescit in manibus eorum.',
        9: 'Interrogavimus ergo senes illos, et ita diximus eis: Quis dedit vobis potestatem ut domum hanc aedificaretis, et muros hos instauraretis?',
        10: 'Sed et nomina eorum quaesivimus ab eis, ut nunciaremus tibi: scripsimusque nomina eorum virorum, qui sunt principes in eis.',
        11: 'Huiuscemodi autem sermonem responderunt nobis, dicentes: Nos sumus servi Dei caeli et terrae, et aedificamus templum, quod erat extructum ante hos annos multos, quodque rex Israel magnus aedificaverat, et extruxerat.',
        12: 'Postquam autem ad iracundiam provocaverunt patres nostri Deum caeli, tradidit eos in manus Nabuchodonosor regis Babylonis Chaldaei, domum quoque hanc destruxit, et populum eius transtulit in Babylonem.',
        13: 'Anno autem primo Cyri regis Babylonis, Cyrus rex proposuit edictum ut domus Dei aedificaretur.',
        14: 'Nam et vasa templi Dei aurea et argentea, quae Nabuchodonosor tulerat de templo, quod erat in Ierusalem, et asportaverat ea in templum Babylonis, protulit Cyrus rex de templo Babylonis, et data sunt Sassabasar vocabulo, quem et principem constituit,',
        15: 'dixitque ei: Haec vasa tolle, et vade, et pone ea in templo, quod est in Ierusalem, et domus Dei aedificetur in loco suo.',
        16: 'Tunc itaque Sassabasar ille venit et posuit fundamenta templi Dei in Ierusalem, et ex eo tempore usque nunc aedificatur, et necdum completum est.',
        17: 'Nunc ergo, si videtur regi bonum, recenseat in bibliotheca regis, quae est in Babylone, utrumnam a Cyro rege iussum fuerit ut aedificaretur domus Dei in Ierusalem, et voluntatem regis super hac re mittat ad nos.',
    },
    6: {
        1: 'Tunc Darius rex praecepit: et recensuerunt in bibliotheca librorum, qui erant repositi in Babylone,',
        2: 'et inventum est in Ecbatanis, quod est castrum in Medena provincia volumen unum, talisque scriptus erat in eo commentarius:',
        3: 'Anno primo Cyri regis: Cyrus rex decrevit ut domus Dei aedificaretur, quae est in Ierusalem, in loco ubi immolent hostias, et ut ponant fundamenta supportantia altitudinem cubitorum sexaginta, et latitudinem cubitorum sexaginta,',
        4: 'ordines de lapidibus impolitis tres, et sic ordines de lignis novis: sumptus autem de domo regis dabuntur.',
        5: 'Sed et vasa templi Dei aurea et argentea, quae Nabuchodonosor tulerat de templo Ierusalem, et attulerat ea in Babylonem, reddantur, et referantur in templum in Ierusalem in locum suum, quae et posita sunt in templo Dei.',
        6: 'Nunc ergo Thathanai dux regionis, quae est trans Flumen, Stharbuzanai, et consiliarii vestri Apharsachaei, qui estis trans Flumen, procul recedite ab illis,',
        7: 'et dimittite fieri templum Dei illud a duce Iudaeorum, et a senioribus eorum, ut domum Dei illam aedificent in loco suo.',
        8: 'Sed et a me praeceptum est quid oporteat fieri a presbyteris Iudaeorum illis ut aedificetur domus Dei, scilicet ut de arca regis, id est, de tributis, quae dantur de regione trans Flumen, studiose sumptus dentur viris illis ne impediatur opus.',
        9: 'Quod si necesse fuerit, et vitulos, et agnos, et hoedos in holocaustum Deo caeli, frumentum, sal, vinum, et oleum, secundum ritum Sacerdotum, qui sunt in Ierusalem, detur eis per singulos dies, ne sit in aliquo querimonia.',
        10: 'Et offerant oblationes Deo caeli, orentque pro vita regis, et filiorum eius.',
        11: 'A me ergo positum est decretum: Ut omnis homo, qui hanc mutaverit iussionem, tollatur lignum de domum ipsius, et erigatur, et configatur in eo, domus autem eius publicetur.',
        12: 'Deus autem, qui habitare fecit nomen suum ibi, dissipet omnia regna, et populum qui extenderit manum suam ut repugnet, et dissipet domum Dei illam, quae est in Ierusalem. Ego Darius statui decretum, quod studiose impleri volo.',
        13: 'Igitur Thathanai dux regionis trans Flumen, et Stharbuzanai, et consiliarii eius, secundum quod praeceperat Darius rex, sic diligenter executi sunt.',
        14: 'Seniores autem Iudaeorum aedificabant, et prosperabantur iuxta prophetiam Aggaei prophetae, et Zachariae filii Addo: et aedificaverunt et construxerunt iubente Deo Israel, et iubente Cyro, et Dario, et Artaxerxe regibus Persarum:',
        15: 'et compleverunt domum Dei istam, usque ad diem tertium mensis Adar, qui est annus sextus Darii regis.',
        16: 'Fecerunt autem filii Israel Sacerdotes et Levitae, et reliqui filiorum transmigrationis, dedicationem Domus Dei in gaudio.',
        17: 'Et obtulerunt in dedicationem domus Dei, vitulos centum, arietes ducentos, agnos quadringentos, hircos caprarum pro peccato totius Israel duodecim, iuxta numerum tribuum Israel.',
        18: 'Et statuerunt Sacerdotes in ordinibus suis, et Levitas in vicibus suis super opera Dei in Ierusalem, sicut scriptum est in libro Moysi.',
        19: 'Fecerunt autem filii Israel transmigrationis, Pascha, quartadecima die mensis primi.',
        20: 'Purificati enim fuerant Sacerdotes et Levitae quasi unus: omnes mundi ad immolandum pascha universis filiis transmigrationis, et fratribus suis Sacerdotibus, et sibi.',
        21: 'Et comederunt filii Israel, qui reversi fuerant de transmigratione, et omnes qui se separaverant a coinquinatione Gentium terrae ad eos, ut quaererent Dominum Deum Israel.',
        22: 'Et fecerunt sollemnitatem azymorum septem diebus in laetitia, quoniam laetificaverat eos Dominus, et converterat cor regis Assur ad eos, ut adiuvaret manus eorum in opere domus Domini Dei Israel.',
    },
    7: {
        1: 'Post haec autem verba in regno Artaxerxis regis Persarum, Esdras filius Saraiae, filii Azariae, filii Helciae,',
        2: 'filii Sellum, filii Sadoc, filii Achitob,',
        3: 'filii Amariae, filii Azariae, filii Maraioth,',
        4: 'filii Zarahiae, filii Ozi, filii Bocci,',
        5: 'filii Abisue, filii Phinees, filii Eleazar, filii Aaron sacerdotis ab initio.',
        6: 'Ipse Esdras ascendit de Babylone, et ipse scriba velox in lege Moysi, quam Dominus Deus dedit Israel: et dedit ei rex secundum manum Domini Dei eius super eum, omnem petitionem eius.',
        7: 'Et ascenderunt de filiis Israel, et de filiis Sacerdotum, et de filiis Levitarum, et de cantoribus, et de ianitoribus, et de Nathinaeis, in Ierusalem anno septimo Artaxerxis regis.',
        8: 'Et venerunt in Ierusalem mense quinto, ipse est annus septimus regis.',
        9: 'Quia in primo die mensis primi coepit ascendere de Babylone, et in primo die mensis quinti venit in Ierusalem, iuxta manum Dei sui bonam super se.',
        10: 'Esdras enim paravit cor suum, ut investigaret legem Domini, et faceret et doceret in Israel praeceptum et iudicium.',
        11: 'Hoc est autem exemplar epistolae edicti, quod dedit rex Artaxerxes Esdrae sacerdoti, scribae erudito in sermonibus et praeceptis Domini, et ceremoniis eius in Israel.',
        12: 'Artaxerxes rex regum Esdrae sacerdoti, scribae legis Dei caeli doctissimo, salutem.',
        13: 'A me decretum est, ut cuicumque placuerit in regno meo de populo Israel, et de Sacerdotibus eius, et de Levitis ire in Ierusalem, tecum vadat.',
        14: 'A facie enim regis, et septem consiliatorum eius missus es, ut visites Iudaeam et Ierusalem in lege Dei tui, quae est in manu tua:',
        15: 'et ut feras argentum et aurum quod rex, et consiliatores eius sponte obtulerunt Deo Israel, cuius in Ierusalem tabernaculum est.',
        16: 'Et omne argentum et aurum quodcumque inveneris in universa provincia Babylonis, et populus offerre voluerit, et de Sacerdotibus quae sponte obtulerint domui Dei sui, quae est in Ierusalem,',
        17: 'libere accipe, et studiose eme de hac pecunia vitulos, arietes, agnos et sacrificia et libamina eorum, et offer ea super altare templi Dei vestri, quod est in Ierusalem.',
        18: 'Sed et si quid tibi, et fratribus tuis placuerit de reliquo argento et auro ut faciatis, iuxta voluntatem Dei vestri facite.',
        19: 'Vasa quoque, quae dantur tibi in ministerium domus Dei tui, trade in conspectu Dei in Ierusalem.',
        20: 'Sed et cetera, quibus opus fuerit in domum Dei tui, quantumcumque necesse est ut expendas, dabitur de thesauro, et de fisco regis,',
        21: 'et a me. Ego Artaxerxes rex, statui atque decrevi omnibus custodibus arcae publicae, qui sunt trans Flumen, ut quodcumque petierit a vobis Esdras sacerdos, scriba legis Dei caeli, absque mora detis',
        22: 'usque ad argenti talenta centum, et usque ad frumenti coros centum, et usque ad vini batos centum, et usque ad batos olei centum, sal vero absque mensura.',
        23: 'Omne, quod ad ritum Dei caeli pertinet, tribuatur diligenter in domo Dei caeli: ne forte irascatur contra regnum regis, et filiorum eius.',
        24: 'Vobis quoque notum facimus de universis Sacerdotibus, et Levitis, et cantoribus, et ianitoribus, Nathinaeis, et ministris domus Dei huius, ut vectigal, et tributum, et annonas non habeatis potestatem imponendi super eos.',
        25: 'Tu autem Esdra secundum sapientiam Dei tui, quae est in manu tua, constitue iudices et praesides ut iudicent omni populo, qui est trans Flumen, his videlicet qui noverunt legem Dei tui, sed et imperitos docete libere.',
        26: 'Et omnis qui non fecerit legem Dei tui, et legem regis diligenter, iudicium erit de eo sive in mortem, sive in exilium, sive in condemnationem substantiae eius, vel certe in carcerem.',
        27: 'Benedictus Dominus Deus patrum nostrorum, qui dedit hoc in corde regis ut glorificaret domum Domini, quae est in Ierusalem,',
        28: 'et in me inclinavit misericordiam suam coram rege et consiliatoribus eius, et universis principibus regis potentibus: et ego confortatus manu Domini Dei mei, quae erat in me, congregavi de Israel principes qui ascenderent mecum.',
    },
    8: {
        1: 'Hi sunt autem principes familiarum, et genealogia eorum, qui ascenderunt mecum in regno Artaxerxis regis de Babylone.',
        2: 'De filiis Phinees, Gersom. De filiis Ithamar, Daniel. De filiis David, Hattus.',
        3: 'De filiis Secheniae, et de filiis Pharos, Zacharias: et cum eo numerati sunt viri centum quinquaginta.',
        4: 'De filiis Phahath Moab, Elioenai filius Zarehe, et cum eo ducenti viri.',
        5: 'De filiis Secheniae, filius Ezechiel, et cum eo trecenti viri.',
        6: 'De filiis Adan, Abed filius Ionathan, et cum eo quinquaginta viri.',
        7: 'De filiis Alam, Isaias filius Athaliae, et cum eo septuaginta viri.',
        8: 'De filiis Saphatiae, Zebedia filius Michael, et cum eo octoginta viri.',
        9: 'De filiis Ioab, Obedia filius Iahiel, et cum eo ducenti decem et octo viri.',
        10: 'De filiis Selomith, filius Iosphiae, et cum eo centum sexaginta viri.',
        11: 'De filiis Bebai, Zacharias filius Bebai, et cum eo vigintiocto viri.',
        12: 'De filiis Azgad, Iohanan filius Eccetan, et cum eo centum et decem viri.',
        13: 'De filiis Adonicam, qui erant novissimi: et haec nomina eorum: Elipheleth, et Iehiel, et Samaias, et cum eis sexaginta viri.',
        14: 'De filii Begui, Uthai et Zachur, et cum eis septuaginta viri.',
        15: 'Congregavi autem eos ad fluvium, qui decurrit ad Ahava, et mansimus ibi tribus diebus: quaesivique in populo et in sacerdotibus de filiis Levi, et non inveni ibi.',
        16: 'Itaque misi Eliezer, et Ariel, et Semeiam, et Elnathan, et Iarib, et alterum Elnathan, et Nathan, et Zachariam, et Mosollam principes: et Ioiarib, et Elnathan sapientes.',
        17: 'Et misi eos ad Eddo, qui est primus in Casphiae loco, et posui in ore eorum verba, quae loquerentur ad Eddo, et fratres eius Nathinaeos in loco Casphiae ut adducerent nobis ministros domus Dei nostri.',
        18: 'Et adduxerunt nobis per manum Dei nostri bonam super nos, virum doctissimum de filiis Moholi filii Levi filii Israel, et Sarabiam et filios eius et fratres eius decem et octo,',
        19: 'et Hasabiam, et cum eo Isaiam de filiis Merari, fratresque eius, et filios eius viginti:',
        20: 'et de Nathinaeis, quos dederat David et principes ad ministeria Levitarum, Nathinaeos ducentos viginti: omnes hi suis nominibus vocabantur.',
        21: 'Et praedicavi ibi ieiunium iuxta fluvium Ahava ut affligeremur coram Domino Deo nostro, et peteremus ab eo viam rectam nobis et filiis nostris, universaeque substantiae nostrae.',
        22: 'Erubui enim petere a rege auxilium et equites, qui defenderent nos ab inimico in via: quia dixeramus regi: Manus Dei nostri est super omnes, qui quaerunt eum in bonitate: et imperium eius et fortitudo eius, et furor super omnes, qui derelinquunt eum.',
        23: 'Ieiunavimus autem, et rogavimus Deum nostrum per hoc: et evenit nobis prospere.',
        24: 'Et separavi de principibus Sacerdotum duodecim, Sarabiam, et Hasabiam, et cum eis de fratribus eorum decem.',
        25: 'appendique eis argentum et aurum, et vasa consecrata domus Dei nostri, quae obtulerat rex et consiliatores eius, et principes eius, universusque Israel eorum, qui inventi fuerant:',
        26: 'et appendi in manibus eorum argenti talenta sexcenta quinquaginta, et vasa argentea centum, auri centum talenta:',
        27: 'et crateres aureos viginti, qui habebant solidos millenos, et vasa aeris fulgentis optimi duo, pulchra, ut aurum.',
        28: 'Et dixi eis: Vos sancti Domini, et vasa sancta, et argentum et aurum, quod sponte oblatum est Domino Deo patrum nostrorum:',
        29: 'vigilate et custodite, donec appendatis coram principibus Sacerdotum, et Levitarum, et ducibus familiarum Israel in Ierusalem, in thesaurum domus Domini.',
        30: 'Susceperunt autem Sacerdotes et Levitae pondus argenti, et auri, et vasorum ut deferrent Ierusalem in domum Dei nostri.',
        31: 'Promovimus ergo a flumine Ahava duodecimo die mensis primi ut pergeremus Ierusalem: et manus Dei nostri fuit super nos, et liberavit nos de manu inimici et insidiatoris in via.',
        32: 'Et venimus Ierusalem, et mansimus ibi tribus diebus.',
        33: 'Die autem quarta appensum est argentum, et aurum, et vasa in domo Dei nostri per manum Meremoth filii Uriae Sacerdotis, et cum eo Eleazar filius Phinees, cumque eis Iozabed filius Iosue, et Noadaia filius Bennoi Levitae,',
        34: 'iuxta numerum et pondus omnium: descriptumque est omne pondus in tempore illo.',
        35: 'Sed et qui venerant de captivitate filii transmigrationis, obtulerunt holocaustomata Deo Israel, vitulos duodecim pro omni populo Israel, arietes nonaginta sex, agnos septuaginta septem, hircos pro peccato, duodecim: omnia in holocaustum Domino.',
        36: 'Dederunt autem edicta regis satrapis, qui erant de conspectu regis et ducibus trans Flumen, et elevaverunt populum et domum Dei.',
    },
    9: {
        1: 'Postquam autem haec completa sunt, accesserunt ad me principes, dicentes: Non est separatus populus Israel, Sacerdotes et Levitae a populis terrarum, et abominationibus eorum Chananaei videlicet, et Hethaei, et Pherezaei, et Iebusaei, et Ammonitarum, et Moabitarum, et Aegyptiorum, et Amorrhaeorum:',
        2: 'tulerunt enim de filiabus eorum sibi et filiis suis, et commiscuerunt semen sanctum cum populis terrarum: manus etiam principum et magistratuum fuit in transgressione hac prima.',
        3: 'Cumque audissem sermonem istum, scidi pallium meum et tunicam, et evelli capillos capitis mei et barbae, et sedi moerens.',
        4: 'Convenerunt autem ad me omnes, qui timebant verbum Dei Israel, pro transgressione eorum, qui de captivitate venerant, et ego sedebam tristis usque ad sacrificium vespertinum:',
        5: 'et in sacrificio vespertino surrexi de afflictione mea, et scisso pallio et tunica, curvavi genua mea, et expandi manus meas ad Dominum Deum meum,',
        6: 'et dixi: Deus meus, confundor et erubesco levare faciem meam ad te: quoniam iniquitates nostrae multiplicatae sunt super caput nostrum, et delicta nostra creverunt usque ad caelum',
        7: 'a diebus patrum nostrorum: sed et nos ipsi peccavimus graviter usque ad diem hanc, et in iniquitatibus nostris traditi sumus ipsi, et reges nostri, et Sacerdotes nostri in manum regum terrarum, et in gladium, et in captivitatem, et in rapinam, et in confusionem vultus, sicut et die hac.',
        8: 'Et nunc quasi parum et ad momentum facta est deprecatio nostra apud Dominum Deum nostrum, ut dimitterentur nobis reliquiae, et daretur nobis paxillus in loco sancto eius, et illuminaret oculos nostros Deus noster, et daret nobis vitam modicam in servitute nostra,',
        9: 'quia servi sumus, et in servitute nostra non dereliquit nos Deus noster, sed inclinavit super nos misericordiam coram rege Persarum, ut daret nobis vitam, et sublimaret domum Dei nostri, et extrueret solitudines eius, et daret nobis sepem in Iuda et Ierusalem.',
        10: 'Et nunc quid dicemus Deus noster post haec? quia dereliquimus mandata tua,',
        11: 'quae praecepisti in manu servorum tuorum prophetarum, dicens: Terra, ad quam vos ingredimini ut possideatis eam, terra immunda est iuxta immunditiam populorum, ceterarumque terrarum, abominationibus eorum qui repleverunt eam ab ore usque ad os in coinquinatione sua.',
        12: 'Nunc ergo filias vestras ne detis filiis eorum, et filias eorum ne accipiatis filiis vestris, et non quaeratis pacem eorum, et prosperitatem eorum usque in aeternum: ut confortemini, et comedatis quae bona sunt terrae, et heredes habeatis filios vestros usque in saeculum.',
        13: 'Et post omnia quae venerunt super nos in operibus nostris pessimis, et in delicto nostro magno, quia tu Deus noster liberasti nos de iniquitate nostra, et dedisti nobis salutem sicut est hodie,',
        14: 'ut non averteremur, et irrita faceremus mandata tua, neque matrimonia iungeremus cum populis abominationum istarum. Numquid iratus es nobis usque ad consummationem ne dimitteres nobis reliquias ad salutem?',
        15: 'Domine Deus Israel iustus es tu: quoniam derelicti sumus, qui salvaremur sicut die hac. Ecce coram te sumus in delicto nostro. non enim stari potest coram te super hoc.',
    },
    10: {
        1: 'Sic ergo orante Esdra, et implorante Deum, et flente, et iacente ante templum Dei, collectus est ad eum de Israel coetus grandis nimis virorum et mulierum et puerorum, et flevit populus fletu multo.',
        2: 'Et respondit Sechenias filius Iehiel de filiis Aelam, et dixit Esdrae: Nos praevaricati sumus in Deum nostrum, et duximus uxores alienigenas de populis terrae: et nunc, si est poenitentia in Israel super hoc,',
        3: 'percutiamus foedus cum Domino Deo nostro, ut proiiciamus universas uxores, et eos qui de his nati sunt iuxta voluntatem Domini, et eorum qui timent praeceptum Domini Dei nostri: secundum legem fiat.',
        4: 'Surge, tuum est decernere, nosque erimus tecum: confortare, et fac.',
        5: 'Surrexit ergo Esdras, et adiuravit principes Sacerdotum et Levitarum, et omnem Israel ut facerent secundum verbum hoc, et iuraverunt.',
        6: 'Et surrexit Esdras ante domum Dei, et abiit ad cubiculum Iohanan filii Eliasib, et ingressus est illuc, panem non comedit, et aquam non bibit: lugebat enim transgressionem eorum, qui venerant de captivitate.',
        7: 'et missa est vox in Iuda et in Ierusalem omnibus filiis transmigrationis, ut congregarentur in Ierusalem:',
        8: 'et omnis qui non venerit in tribus diebus iuxta consilium principum et seniorum, auferetur universa substantia eius, et ipse abiicietur de coetu transmigrationis.',
        9: 'Convenerunt igitur omnes viri Iuda, et Beniamin in Ierusalem tribus diebus, ipse est mensis nonus, vigesimo die mensis: et sedit omnis populus in platea domus Dei, trementes pro peccato, et pluviis.',
        10: 'Et surrexit Esdras sacerdos, et dixit ad eos: Vos transgressi estis, et duxistis uxores alienigenas ut adderetis super delictum Israel.',
        11: 'Et nunc date confessionem Domino Deo patrum vestrorum, et facite placitum eius, et separamini a populis terrae, et ab uxoribus alienigenis.',
        12: 'Et respondit universa multitudo, dixitque voce magna: Iuxta verbum tuum ad nos, sic fiat.',
        13: 'Verumtamen quia populus multus est, et tempus pluviae, et non sustinemus stare foris, et opus non est diei unius vel duorum (vehementer quippe peccavimus in sermone isto)',
        14: 'constituantur principes in universa multitudine: et omnes in civitatibus nostris qui duxerunt uxores alienigenas veniant in temporibus statutis, et cum his seniores per civitatem et civitatem, et iudices eius donec avertatur ira Dei nostri a nobis super peccato hoc.',
        15: 'Igitur Ionathan filius Azahel, et Iaasia filius Thecue, steterunt super hoc, et Messollam et Sebethai Levites adiuverunt eos:',
        16: 'Feceruntque sic filii transmigrationis. Et abierunt Esdras Sacerdos, et viri principes familiarum in domos patrum suorum, et omnes per nomina sua, et sederunt in die primo mensis decimi ut quaererent rem.',
        17: 'Et consummati sunt omnes viri, qui duxerant uxores alienigenas, usque ad diem primam mensis primi.',
        18: 'Et inventi sunt de filiis sacerdotum qui duxerant uxores alienigenas. De filiis Iosue filii Iosedec, et fratres eius, Maasia, et Eliezer, et Iarib, et Godolia.',
        19: 'Et dederunt manus suas ut eiicerent uxores suas, et pro delicto suo arietem de ovibus offerrent.',
        20: 'Et de filiis Emmer, Hanani, et Zebedia.',
        21: 'Et de filiis Harim, Maasia, et Elia, et Semeia, et Iehiel, et Ozias.',
        22: 'Et de filiis Pheshur, Elioenai, Maasia, Ismael, Nathanael, Iozabed, et Elasa.',
        23: 'Et de filiis Levitarum, Iosabed, et Semei, et Celaia, ipse est Calita, Phataia, Iuda, et Eliezer.',
        24: 'Et de cantoribus, Eliasib. Et de ianitoribus, Sellum, et Telem, et Uri.',
        25: 'Et ex Israel, de filiis Pharos, Remeia, et Iesia, et Melchia, et Miamin, et Eliezer, et Melchia, et Banea.',
        26: 'Et de filiis Aelam, Mathania, Zacharias, et Iehiel, et Abdi, et Ierimoth, et Elia.',
        27: 'Et de filiis Zethua, Elioenai, Eliasib, Mathania, et Ierimuth, et Zabad, et Aziza.',
        28: 'Et de filiis Bebai, Iohanan, Hanania, Zabbai, Athalai.',
        29: 'Et de filiis Bani, Mosollam, et Melluch, et Adaia, Iasub, et Saal, et Ramoth.',
        30: 'Et de filiis Phahath Moab, Edna, et Chalal, Bananias, et Maasias, Mathanias, Beseleel, Bennui, et Manasse.',
        31: 'Et de filiis Herem, Eliezer, Iesue, Melchias, Semeias, Simeon,',
        32: 'Beniamin, Maloch, Samarias.',
        33: 'Et de filiis Hasom, Mathanai, Mathatha, Zabad, Eliphelet, Iermai, Manasse, Semei.',
        34: 'De filiis Bani, Maadi, Amram, et Vel,',
        35: 'Baneas, et Badaias, Cheliau,',
        36: 'Vania, Marimuth, et Eliasib,',
        37: 'Mathanias, Mathanai, et Iasi,',
        38: 'et Bani, et Bennui, Semei,',
        39: 'et Salmias, et Nathan, et Adaias,',
        40: 'et Mechnedebai, Sisai, Sarai,',
        41: 'Ezrel, et Selemiau, Semeria,',
        42: 'Sellum, Amaria, Ioseph.',
        43: 'De filiis Nebo, Iehiel, Mathathias, Zabad, Zabina, Ieddu, et Ioal, et Banaia.',
        44: 'Omnes hi acceperant uxores alienigenas, et fuerunt ex eis mulieres, quae pepererant filios.',
    },
}
